"""Evaluate one frozen virtual-laboratory observation task; never controls hardware."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
from experiment_management.run import RunRecorder,sha256_bytes,strict_json_bytes,write_json_pair
RID="EXP-20260921-002-virtual-laboratory-static-observation-task";ROOT=Path(__file__).resolve().parents[2];CFG=ROOT/"research/configs"/f"{RID}.json";OUT=ROOT/"research/artifacts"/RID;RESULT=ROOT/"research/reports"/f"{RID}.result.json";RECORD=ROOT/"research/experiments"/f"{RID}.record.json"
def file_hash(path:Path)->str:return "sha256:"+hashlib.sha256(path.read_bytes()).hexdigest()
def main()->None:
 if OUT.exists() or RESULT.exists() or RECORD.exists():raise FileExistsError("refusing overwrite")
 cfg=json.loads(CFG.read_text());p=cfg["blocking_predecessor"];result_path=ROOT/p["result_path"];state_path=ROOT/p["state_path"];prior=json.loads(result_path.read_text());state=json.loads(state_path.read_text())
 if file_hash(result_path)!=p["result_sha256"] or file_hash(state_path)!=p["state_sha256"] or prior["status"]!="passed_pending_human_review":raise RuntimeError("virtual-laboratory predecessor is not frozen and technically passed")
 task=cfg["task"];rec=RunRecorder(run_id=RID,objective="Evaluate one simulator-label static observation task from a frozen virtual laboratory.",script=Path(__file__),repo_root=ROOT,output_root=ROOT/"research/runs",parameters=task,random_seed=None,inputs=[{"kind":"configuration","path":CFG.relative_to(ROOT).as_posix(),"sha256":file_hash(CFG)},{"kind":"virtual_lab_result","path":result_path.relative_to(ROOT).as_posix(),"sha256":file_hash(result_path)},{"kind":"virtual_lab_state","path":state_path.relative_to(ROOT).as_posix(),"sha256":file_hash(state_path)}],baseline={"kind":"frozen_virtual_laboratory","reference":p["run_id"]},level="formal")
 with rec:
  OUT.mkdir(parents=True);(OUT/"config.json").write_bytes(strict_json_bytes(cfg));fixed={name:value for name,value in state["cameras"].items() if name.startswith("fixed_depth_")};visible=[name for name,value in fixed.items() if value["cup_segmentation_pixels"]>0];terminal=task["success_terminal_assessment"] if visible else task["failure_terminal_assessment"];passed=bool(visible);assessment={"task_id":task["id"],"terminal_assessment":terminal,"fixed_camera_evidence":fixed,"contributing_cameras":visible,"wrist_camera_evidence":state["cameras"]["wrist_cam"],"simulator_labels_only":True};(OUT/"terminal-assessment.json").write_bytes(strict_json_bytes(assessment));result={"schema_version":"first-robots/research-result/v1","run_id":RID,"status":"passed_pending_human_review" if passed else "blocked_pending_human_review","observations":assessment,"limits":cfg["non_claims"],"review":{"status":"pending_human_review","adopted":False}};record={"schema_version":"first-robots/experiment-record/v1","run_id":RID,"kind":"formal_virtual_laboratory_static_observation_task","result":{"path":RESULT.relative_to(ROOT).as_posix(),"sha256":sha256_bytes(strict_json_bytes(result))},"review":{"status":"pending_human_review"}};write_json_pair(first_path=RECORD,first_content=record,second_path=RESULT,second_content=result)
  for path in sorted(OUT.iterdir()):rec.add_artifact(path)
  rec.add_artifact(RESULT);rec.add_artifact(RECORD);rec.add_metric("contributing_fixed_cameras",len(visible),"cameras");rec.complete(passed=passed,criteria="At least one named nominal fixed camera must have nonzero simulator cup segmentation pixels.",review_status="pending_human_review",note="Simulator-label terminal assessment only.")
